export const H = etiqueta(ROOT) === "H" ? ROOT : HERMANO;
export const CONTRATOS = path.join(T, "verdad", "contratos.json");
const leer = (p) => (fs.existsSync(p) ? fs.readFileSync(p, "utf8") : null);
const get = (o, ruta) => ruta.replace(/\[(\d+)\]/g, ".$1").split(".").reduce((a, k) => (a == null ? undefined : a[k]), o);

/** Comprueba una fila. Devuelve { id, checks: {contrato, validador, ui, material, guard}, hecho }. Cada check = { ok, detalle }. */
export function comprobarFila(row, ctx = contexto()) {
  const clave = row.clave ?? row.ruta.split(".").pop();
  const c = {};
  // (1) contrato
  c.contrato = ctx.contratosMd == null ? { ok: false, detalle: "sin CONTRATOS-HUECOS.md" } : ctx.contratosMd.includes(row.contrato?.campo ?? "�") ? { ok: true, detalle: row.contrato.campo } : { ok: false, detalle: `«${row.contrato?.campo}» no está en CONTRATOS-HUECOS.md` };
